CatPaw.showToast('\u4EE3\u7406\u670D\u52D9\u4F4D\u5740\u683C\u5F0F\u4E0D\u6B63\u78BA\uFF0C\u9700\u4EE5 http:// \u6216 https:// \u958B\u982D', 'error');
document.getElementById('proxyBase').focus();
